// Asset library only. Money and account authority stay with the existing
// Player session bridge and Railway double-entry ledger.
export const RELEASE='superwin-expansion100-20261108-r1';
export const PREFIX='/native-expansion100/';
const json=(data,status=200)=>Response.json(data,{status,headers:{'cache-control':'no-store','x-content-type-options':'nosniff','x-zplay-expansion':RELEASE}});
const csp="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; media-src 'self'; connect-src 'self'; frame-ancestors 'self'; object-src 'none'; base-uri 'none'";
export function createLibrary(releases=[]){
 const published=new Map();
 for(const r of releases){
  if(!/^exp100_[a-z0-9]+$/.test(r.id)||!r.version||!r.entry.startsWith(PREFIX+r.id+'/')||r.status!=='published'||!r.referenceVerified||!r.browserVerified||!r.ledgerVerified||!r.backendVerified)throw Error('INCOMPLETE_GAME_RELEASE');
  if(published.has(r.id))throw Error('DUPLICATE_GAME_RELEASE');published.set(r.id,Object.freeze({...r}));
 }
 return {async fetch(request,env){
  const url=new URL(request.url),path=url.pathname,read=request.method==='GET'||request.method==='HEAD';
  if(!read)return json({error:'METHOD_NOT_ALLOWED'},405);
  if(path===PREFIX+'health')return json({service:'superwin-library-100',release:RELEASE,targetGames:100,publishedGames:published.size,ready:true,walletAuthority:'existing-player-railway-ledger'});
  if(path===PREFIX+'catalog')return json({release:RELEASE,games:[...published.values()].map(r=>({id:r.id,name:r.name,version:r.version,launch:'/games/'+r.id,thumbnail:r.cover,available:true,enabled:true,demo:false,studio:'Superwin',referenceProvider:r.provider,official_provider_game:false}))});
  let target=path;
  if(path.startsWith('/games/')){const release=published.get(path.slice(7));if(!release)return json({error:'GAME_NOT_PUBLISHED'},404);target=release.entry;}
  else if(path.startsWith(PREFIX)){
   const id=path.slice(PREFIX.length).split('/')[0];if(!published.has(id))return json({error:'GAME_NOT_PUBLISHED'},404);
  }else return json({error:'NOT_FOUND'},404);
  if(!env.ASSETS)return json({error:'ASSETS_UNAVAILABLE'},503);
  const asset=await env.ASSETS.fetch(new Request(new URL(target,url.origin),{method:request.method}));
  const headers=new Headers(asset.headers);headers.set('x-zplay-expansion',RELEASE);headers.set('x-content-type-options','nosniff');
  if(headers.get('content-type')?.includes('text/html')){headers.set('content-security-policy',csp);headers.set('cache-control','no-store');}
  return new Response(request.method==='HEAD'?null:asset.body,{status:asset.status,headers});
 }};
}
export default createLibrary();
